(() => {
  if (window.__qf_hook) return 'already';
  window.__qf_hook = true;
  window.__qf_log = [];
  window.__qf_last = null;
  window.__qf_create = null;
  const hit = (u) => /\/api\/cas\/customer\/web\/qr-code/.test(String(u));
  const stash = (u, txt) => {
    window.__qf_log.push({ u: String(u).slice(0, 240), t: String(txt).slice(0, 1200) });
    try {
      const j = JSON.parse(txt);
      const d = j && j.data;
      if (d && d.url && /loginconfirm/.test(String(d.url))) {
        window.__qf_create = j;
        window.__qf_last = j;
      } else if (d && d.id && d.status != null) {
        window.__qf_status = j;
      } else if (!window.__qf_last) {
        window.__qf_last = j;
      }
    } catch (e) {}
  };
  const O = XMLHttpRequest.prototype.open, S = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.open = function (m, u) {
    this.__qf_u = String(u);
    return O.apply(this, arguments);
  };
  XMLHttpRequest.prototype.send = function () {
    if (hit(this.__qf_u)) this.addEventListener('loadend', () => stash(this.__qf_u, this.responseText));
    return S.apply(this, arguments);
  };
  const F = window.fetch;
  window.fetch = function (u) {
    const us = String(typeof u === 'object' && u ? u.url : u);
    const p = F.apply(this, arguments);
    if (hit(us)) return p.then((r) => { r.clone().text().then((t) => stash(us, t)).catch(() => {}); return r; });
    return p;
  };
  return 'hooked';
})()

args.script:
(function () {
  var icon = document.querySelector('.beer-login-container img.css-wemwzq');
  if (!icon) throw new Error('beer-login QR icon .css-wemwzq missing');
  icon.click();
  return 'clicked-qr-icon';
})()

(function () {
  var create = window.__qf_create || null;
  var data = create && create.data;
  if (!(data && data.url && /loginconfirm/.test(data.url))) {
    var logs = window.__qf_log || [];
    for (var i = logs.length - 1; i >= 0; i--) {
      try {
        var j = JSON.parse(logs[i].t);
        if (j && j.data && j.data.url && /loginconfirm/.test(j.data.url)) {
          create = j; data = j.data; break;
        }
      } catch (e) {}
    }
  }
  if (!(data && data.url)) {
    throw new Error('CAS qr-code create missing — log=' + JSON.stringify((window.__qf_log || []).slice(-3)).slice(0, 500));
  }
  if (!/customer\.xiaohongshu\.com\/loginconfirm/.test(data.url)) {
    throw new Error('refusing non-loginconfirm QR url: ' + String(data.url).slice(0, 160));
  }
  if (/www\.xiaohongshu\.com\/mobile\/login/.test(data.url)) {
    throw new Error('C-end mobile/login URL — wrong path (edith). Use beer-login CAS only.');
  }
  var channels = data.support_qr_code_channel_infos || data.supportQrCodeChannelInfos || [];
  var names = channels.map(function (c) { return c && c.app_name; }).filter(Boolean);
  if (names.indexOf('千帆') < 0) {
    throw new Error('千帆 not in support channels: ' + JSON.stringify(names));
  }
  window.__qf_qr = { id: data.id, url: data.url, channels: names };
  return JSON.stringify({ qr_id: data.id, url: data.url, channels: names, code: create && create.code });
})()

(function () {
  var img = document.querySelector('img.css-1lhmg90');
  if (!img || !(img.src || '').startsWith('data:image')) {
    img = [].slice.call(document.querySelectorAll('.beer-login-container img')).find(function (i) {
      return (i.src || '').indexOf('data:image') === 0 && (i.src || '').length > 2000;
    });
  }
  if (!img) throw new Error('page QR data URL missing inside beer-login');
  return img.src;
})()

