(function () {
  var host = location.hostname || '';
  var href = location.href || '';
  var text = (document.body && document.body.innerText) || '';
  if (host.indexOf('ark.xiaohongshu.com') < 0) return false;
  if (/\/login/.test(location.pathname)) return false;
  if (/customer\.xiaohongshu\.com\/login/.test(href)) return false;
  if (/登录凭证已过期|请重新登录|登录加载中/.test(text)) return false;
  if (/[?&]ticket=/.test(href)) return false;
  return true;
})()

args.script:
(async function () {
  var seller = null;
  try {
    var r = await fetch('/api/edith/seller/info/v2', { credentials: 'include', headers: { 'content-type': 'application/json' } });
    var t = await r.text();
    var j = null; try { j = JSON.parse(t); } catch (e) {}
    seller = { http: r.status, code: j && j.code, success: j && j.success, msg: j && j.msg, deactivated: j && j.data && j.data.deactivated, company: j && j.data && j.data.company_name };
  } catch (e) { seller = { err: String(e) }; }
  if (!(seller && seller.success)) {
    throw new Error('ark landed but seller/info not ok: ' + JSON.stringify(seller));
  }
  return JSON.stringify({ url: location.href, title: document.title, seller: seller });
})()
